#!/usr/bin/env python3
"""
S2 中诊 · 批次D升级脚本
第二单元 问诊 (16 points) — 症状推导型 derive-box
"""

import re, sys

FILE = 's2-zhongzhen.js'
BAK  = 's2-zhongzhen.js.bak-D'

# ── 1. Read file ──
with open(FILE, 'r', encoding='utf-8') as f:
    content = f.read()
orig_content = content

# ── 2. Define new core content for each point ──
# Symptoms-deduction type: step1 (概念引出·蓝) → step2 (病机分析·红) → step3 (分型锁定·紫) → step4 (鉴别·橙) → step5 (场景变体·橙)
# Plus derive-flow linking nodes

new_content_map = {}

# ═══════════════════════════════════════════
# dx-2-1 恶寒发热的临床意义
# ═══════════════════════════════════════════
new_content_map['dx-2-1'] = '''<p><strong>恶寒发热并见是表证的标志性特征——分辨风寒与风热的关键在于寒热的轻重对比。</strong></p><div class="classic-quote">《素问·风论》："风气藏于皮肤之间，内不得通，外不得泄。"风邪袭表，腠理开阖失常，卫气与邪气相争则恶寒发热并见。<span class="src">——《黄帝内经》</span></div><div class="mnem">恶寒发热并见表，寒重热轻属风寒；热重寒轻属风热，发热恶风太阳中。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">恶寒发热<br>表证标志</span><span class="df-arrow">→</span><span class="df-node df-logic">卫气趋表抗邪<br>正邪交争于表<br>营卫失调</span><span class="df-arrow">→</span><span class="df-node df-organ">寒重→风寒<br>热重→风热<br>恶风→中风</span><span class="df-arrow">→</span><span class="df-node df-symptom">辛温vs辛凉<br>麻黄·桂枝·银翘</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">同一个"发烧怕冷"，背后可能有完全不同的故事</span><div class="ds-body">两个人同时说"我发烧又怕冷"，一个可能裹着被子还瑟瑟发抖（寒重热轻），另一个可能浑身发烫只想掀被子（热重寒轻）。同样是恶寒发热，一个来自寒邪（风寒表证），一个来自热邪（风热表证）。中医问诊的第一步就要辨清：你是怕冷重还是发热重？这个简单的比较直接决定了后面的用药方向——用热药还是凉药。所以问诊时不能只问"你发烧吗"，还要追问"你更怕冷还是更怕热"。</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">恶寒发热的病机分析——卫气在"打仗"</span><div class="ds-body">恶寒发热同时出现的根本原因是"卫气趋表抗邪"——人体的防御力量（卫气）被调集到体表和外邪交战。当外邪刚刚侵犯皮毛，卫气立即奔赴体表"迎战"：卫气被风寒之邪郁遏在肌表不能正常散布→人感觉怕冷（恶寒）；同时人体自发地升高产热来"燃烧"外邪→所以发热。这就是为什么恶寒发热总是一起出现——它们是同一场"战斗"的两个侧面。风寒之邪较重，把卫气"封"得更紧→恶寒重（怕冷明显）；风热之邪偏散，产热反应更强→发热重（发烧更突出）。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——同是恶寒发热，寒热轻重不同指向不同的证</span><div class="ds-body">恶寒发热可细分为三种类型：<strong>风寒表证</strong>——恶寒重发热轻（怕冷明显超过发热），伴头身痛、无汗、口不渴、苔薄白、脉浮紧。病机为风寒束表、卫阳被郁。代表方荆防败毒散或麻黄汤。<strong>风热表证</strong>——发热重恶寒轻（发热明显，怕冷轻微），伴咽痛、口渴、汗出、苔薄黄、脉浮数。病机为风热犯表、肺卫失宣。代表方银翘散。<strong>太阳中风证</strong>——发热轻恶风自汗（微微发热同时怕风、出汗），伴鼻鸣干呕、脉浮缓。病机为营卫不和、腠理疏松。代表方桂枝汤。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——风寒与风热最容易误判的两种情况</span><div class="ds-body">风寒和风热看似一清二楚，实际临床中最容易误判的是以下两种情况：第一，"寒包火"——病人同时有怕冷（风寒）和咽痛口渴（风热）的表现。这时要看哪个更突出：若怕冷重、咽痛轻→风寒为主，银翘散加麻黄；若发热重、怕冷轻、咽痛明显→风热为主。第二，风寒化热——起病时是典型的怕冷重（风寒），三天后变成了发热重（已化热）。这不是判断错了，是病程进展了——初期用辛温、后期改用辛凉。鉴别要点：风寒口不渴、苔白、脉浮紧；风热口渴、苔黄、脉浮数。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是恶寒发热，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（青壮年 vs 老人）：一位25岁小伙子受凉后恶寒重、发热39度、身痛无汗——正气充足、正邪交争剧烈→典型风寒表实证，麻黄汤。一位70岁老人同样受凉后微恶寒、低热37.5度、乏力——正气已衰、反应能力下降→荆防败毒散轻剂，加黄芪扶正。<strong>场景二</strong>（夏季 vs 冬季）：夏季恶寒发热→多夹暑湿（身热不扬、头重如裹），新加香薷饮。冬季恶寒发热→多纯风寒，麻黄汤。<strong>场景三</strong>（小儿 vs 成人）：小儿恶寒发热易传变→很快从风寒转为风热→高热惊厥风险，银翘散加钩藤，密切观察。</div></div></div>'''

# ═══════════════════════════════════════════
# dx-2-2 但寒不热的临床意义
# ═══════════════════════════════════════════
new_content_map['dx-2-2'] = '''<p><strong>但寒不热——只觉怕冷、没有发热，是里寒证的标志，需辨清新病实寒还是久病虚寒。</strong></p><div class="classic-quote">《素问·阴阳应象大论》："阴盛则阳病，阳盛则阴病。阳胜则热，阴胜则寒。"但寒不热为阴气偏盛或阳气不足所致。<span class="src">——《黄帝内经》</span></div><div class="mnem">但寒不热里寒证，新病实寒理中汤；久病虚寒肾气丸，新久虚实要辨清。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">但寒不热<br>里寒证标志</span><span class="df-arrow">→</span><span class="df-node df-logic">阴寒内盛<br>或阳虚失温</span><span class="df-arrow">→</span><span class="df-node df-organ">新病→实寒<br>久病→虚寒</span><span class="df-arrow">→</span><span class="df-node df-symptom">实寒→理中<br>虚寒→肾气丸</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">同样是"怕冷"——一个刚刚着凉，一个已经冷了很久</span><div class="ds-body">两个人走进诊室都说"怕冷"。一个说"昨天淋了雨就开始冷"，另一个说"这个冷已经好几年了，每年冬天都更重"。前者是新发的但寒不热——可能只是一场急性里寒；后者是长期的但寒不热——身体已经"冷"了很久，阳气不足了。问诊的关键是追问"什么时候开始的""多久了"——新病恶寒多为实寒（寒邪直接侵犯脏腑），久病恶寒多为虚寒（自身阳气不足、温煦失职）。</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">但寒不热的病机分析——"体内暖气停了"</span><div class="ds-body">但寒不热的本质是阳气无法温煦全身——要么是外来的寒邪太重，"冻住"了脏腑功能（实寒），要么是自身的阳气不够、产热不足（虚寒）。实寒证：寒邪直中脏腑→局部阳气被寒邪"困住"→表现急性剧烈的怕冷+腹部冷痛。这就像大冬天突然往屋里灌了一股冷风——屋子本身是暖的，但冷风到来瞬间降温。虚寒证：阳气长期亏虚→全身温煦功能减退→慢性持续的怕冷+四肢不温。这就像炉子里煤不够了——不是冷风进来了，而是自身发热不足了。两者的鉴别要点除了病程之外，还要看舌脉——实寒舌苔白厚、脉沉实有力；虚寒舌淡胖齿痕、脉沉迟无力。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——新病恶寒与久病恶寒的鉴别要点</span><div class="ds-body"><strong>实寒证（新病恶寒）</strong>：起病急、病程短。怕冷明显但体温不一定低。伴脘腹冷痛、得温痛减、面色苍白、手足冷。大便溏薄或泄泻、小便清长。舌淡苔白厚、脉沉实或沉紧。病机为寒邪直中或过食生冷→阴寒内盛、阳气被遏。代表方理中汤（温中散寒）。<strong>虚寒证（久病恶寒）</strong>：起病缓慢、病程长。长期怕冷、四肢不温、腰膝酸冷。伴神疲乏力、少气懒言、大便稀溏、小便清长或夜尿多。舌淡胖有齿痕、苔白润、脉沉迟无力。病机为阳气虚衰、温煦失职。代表方金匮肾气丸（温补肾阳）。实寒以祛邪为主（散寒），虚寒以扶正为主（温阳）。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——但寒不热和恶寒发热中最容易混淆的情况</span><div class="ds-body">最容易误判的是"但寒不热"和"恶寒发热"中的寒重热轻：前者是里证（只寒不热），后者是表证（寒重但仍有发热）。区别的关键在于——测体温和问体感。恶寒发热（寒重热轻）→病人明明说"怕冷很重"但体温一量38.5度→表证。但寒不热→病人说"好冷"体温36度甚至偏低→里寒证。另外，但寒不热中的新病恶寒（实寒）和久病恶寒（虚寒）也可通过"喝热水的感觉"鉴别：实寒→喝热水后冷痛明显减轻（寒邪被温散）；虚寒→喝了热水感觉改善不明显（自身火力不足，需要持续温补）。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是但寒不热，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（急性vs慢性）：一位年轻人夏天狂吃冰西瓜后突然腹痛怕冷、大便水样→实寒证，理中汤加藿香。一位老年女性多年怕冷、夏天还要穿秋裤、夜尿3-4次→虚寒证，金匮肾气丸长期调理。<strong>场景二</strong>（女性经期）：经期但寒不热伴小腹冷痛、得热痛减→寒凝胞宫，温经汤。若经期后怕冷加头晕乏力→血虚寒凝，当归四逆汤。<strong>场景三</strong>（地域差异）：北方人冬季但寒不热多纯寒证；南方人但寒不热多夹湿（怕冷+身重+苔白腻）→胃苓汤加减。</div></div></div>'''

# ═══════════════════════════════════════════
# dx-2-3 但热不寒的临床意义
# ═══════════════════════════════════════════
new_content_map['dx-2-3'] = '''<p><strong>但热不寒——只发热不怕冷，是里热证的标志，需分辨壮热、潮热的不同类型和临床意义。</strong></p><div class="classic-quote">《素问·阴阳应象大论》："阳盛则热。"但热不寒为阳热亢盛或阴虚阳亢所致。<span class="src">——《黄帝内经》</span></div><div class="mnem">壮热大汗白虎汤，日晡潮热承气汤；午后湿温三仁汤，夜间阴虚六味黄。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">但热不寒<br>里热证标志</span><span class="df-arrow">→</span><span class="df-node df-logic">阳热亢盛<br>或阴虚火旺</span><span class="df-arrow">→</span><span class="df-node df-organ">壮热·日晡<br>午后·夜间</span><span class="df-arrow">→</span><span class="df-node df-symptom">白虎·承气<br>三仁·六味</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">同样说"发烧"——体温曲线的"时间密码"藏着病根</span><div class="ds-body">两个病人都说"发烧"。一个24小时持续高热、满头大汗、想喝冰水；另一个每到下午三四点体温就准时升高、像潮水一样涨退。虽然都是发热，但前者是"壮热"——整个身体在"燃烧"，后者是"潮热"——发热像潮汐一样有节律。中医问诊中要仔细问清楚发热的时间规律：什么时间烧？一天几次？每次持续多久？这些信息直接指向不同的病机和治法。辨发热类型是但热不寒问诊的核心。</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">但热不寒的病机分析——"体内的火失控了"</span><div class="ds-body">但热不寒的本质是体内产热过多或散热能力下降——阳热亢盛。没有恶寒说明病邪已经不在体表，而是深入了脏腑气血。壮热（高热持续不退、体温39度以上）→阳明气分热盛→正气不虚、邪正剧烈交争→全身都在"烧"→白虎汤。潮热（定时发热如潮汐）→有三种可能：日晡潮热（下午3-5点申时发热）→阳明腑实、热结胃肠→大承气汤；午后潮热（中午过后发热）→湿遏热伏、湿热交蒸→三仁汤；夜间潮热（入夜发热、晨起消退）→阴虚火旺、阴不制阳→六味地黄丸。壮热的特点是"量"（体温高、持续），潮热的特点是"时间"（有节律、定时发）。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——四种发热类型各有不同的信号</span><div class="ds-body"><strong>壮热（高热持续）</strong>——体温39度以上持续不退，伴大汗出、大烦渴（想喝冰水）、面红、脉洪大。病机为阳明气分热盛，热势弥漫全身。代表方白虎汤。若壮热伴腹满便秘、烦躁谵语→阳明腑实，用大承气汤（白虎清气、承气攻下，注意区别）。<strong>日晡潮热（申时发热）</strong>——每日下午3-5点发热明显，伴腹部硬满疼痛、便秘或热结旁流、烦躁、舌红苔黄燥起刺、脉沉实有力。病机为阳明腑实、燥屎内结→热从内发。代表方大承气汤。<strong>午后潮热（午后发热）</strong>——身热不扬（皮肤初摸不热、久摸才感觉烫）、午后热甚、伴头身困重、胸闷脘痞、苔黄腻。病机为湿遏热伏、湿热交蒸。代表方三仁汤。<strong>夜间潮热（入夜发热）</strong>——夜间发热、骨蒸潮热（骨头里往外透热）、五心烦热、盗汗、口干、舌红少苔、脉细数。病机为阴虚阳亢、虚火内扰。代表方六味地黄丸或清骨散。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——壮热与潮热、不同潮热之间最容易误判的情况</span><div class="ds-body">壮热和潮热的鉴别：壮热是体温一直高（持续性），潮热是体温有"起落"（规律性）。壮热病人会说"整天都烧"，潮热病人会说"每天下午/晚上才烧"。日晡潮热和午后潮热的鉴别：日晡潮热→便秘+腹满+苔黄燥→实热（大承气汤）；午后潮热→身重+脘痞+苔黄腻→湿热（三仁汤）。一为燥屎内结（干），一为湿热交蒸（黏）。夜间潮热和午后潮热的鉴别：夜间潮热→舌红少苔+盗汗→阴虚（虚热）；午后潮热→苔黄腻+脘痞→湿热（实热夹湿）。虚热和实热最核心的鉴别在舌象——虚热舌红少苔无苔，实热舌红苔黄腻。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是但热不寒，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（小儿 vs 成人）：小儿壮热极易惊厥（热极生风）→白虎汤加羚羊角、钩藤。成人壮热多伴脱水→白虎汤加人参（白虎加人参汤）。<strong>场景二</strong>（术后 vs 产后）：术后低热（午后或夜间）多瘀血发热→血府逐瘀汤；产后低热多血虚发热→当归补血汤。两者都是虚证为主，但病机不同。<strong>场景三</strong>（季节差异）：夏季但热不寒多夹暑湿（壮热+心烦+呕恶）→白虎加苍术汤。冬季但热不寒多纯热证。</div></div></div>'''

# ═══════════════════════════════════════════
# dx-2-4 寒热往来的临床意义
# ═══════════════════════════════════════════
new_content_map['dx-2-4'] = '''<p><strong>寒热往来——恶寒与发热交替出现，是半表半里证的特征，需分辨发有定时与发无定时的不同。</strong></p><div class="classic-quote">《伤寒论》第96条："伤寒五六日，中风，往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕……小柴胡汤主之。"<span class="src">——《伤寒论》</span></div><div class="mnem">寒热往来半表里，无定小柴有定疟；少阳和解小柴胡，疟疾达原或截疟。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">寒热往来<br>半表半里</span><span class="df-arrow">→</span><span class="df-node df-logic">邪正交争于<br>表里之间</span><span class="df-arrow">→</span><span class="df-node df-organ">无定时→少阳<br>有定时→疟疾</span><span class="df-arrow">→</span><span class="df-node df-symptom">小柴胡和解<br>达原饮化浊</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">"一阵冷一阵热"——不是表证也不是里证，而是"夹在中间"</span><div class="ds-body">病人说"我一阵冷得要命、一阵又热得出汗，来回交替"。这和恶寒发热（同时出现）完全不同——寒热往来是交替出现：冷的时候不热、热的时候不冷。这说明病邪不在表（不在皮毛）、也不在里（不在脏腑），而是"卡"在了半表半里的位置——少阳经和膜原之间。张仲景在《伤寒论》中把这种情况归为少阳病，治法既不能用汗法（不在表）、也不能用下法（不在里），而是用"和法"——和解少阳。</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">寒热往来的病机分析——"邪气在门缝里进进出出"</span><div class="ds-body">寒热往来的病机可以理解为"邪气在表里之间拉锯"：当邪气向表（靠近体表）→正邪交争→发热；当邪气向里（退回半表里）→正气不争→恶寒。形成"寒—热—寒—热"交替的周期性反应。如果寒热往来的时间没有规律（发无定时）→邪在少阳经。少阳位于太阳（表）和阳明（里）之间，是阳气出入的枢纽。用小柴胡汤和解少阳。如果寒热往来的时间固定（发有定时）→邪伏膜原。疟邪在膜原发作有节律，典型疟疾每隔一天或三天发作一次。用达原饮开达膜原。两者的共同点是邪气不在表也不在里，区别在于病位的深浅：少阳较浅（经络），膜原较深（半表半里深层）。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——发无定时的少阳病与发有定时的疟疾</span><div class="ds-body"><strong>少阳病（发无定时）</strong>——寒热往来没有固定时间规律，伴胸胁苦满（两胁胀闷不舒服）、默默不欲饮食、心烦喜呕、口苦咽干目眩。舌苔薄白或薄黄、脉弦。核心病机：邪犯少阳、枢机不利、正邪分争。代表方小柴胡汤（柴胡为君，疏透少阳半表之邪）。要记住少阳病四大主症：往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕。<strong>疟疾（发有定时）</strong>——寒热往来有严格的周期性（一日一次、间日一次或三日一次），发作时先寒战（恶寒发抖）→后高热→大汗出→热退身凉。伴头痛、乏力。舌苔白腻、脉弦滑。核心病机：疟邪伏于膜原、与正气交争而作。代表方达原饮（开达膜原、辟秽化浊）。寒战明显用柴胡桂枝干姜汤，热重用白虎加桂枝汤。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——少阳病和疟疾最容易被误判的情况</span><div class="ds-body">少阳病和疟疾都以寒热往来为特征，但鉴别点是"时间的规律性"：少阳病→发无定时（今天上午冷热、明天下午冷热）→不具备严格的周期性→小柴胡汤。疟疾→发有定时（隔日一次、定时而发）→有严格的发作节律→达原饮。另外还要注意：有些疟疾早期可能节律不明显，但血涂片查疟原虫可确诊。另外还需注意寒热往来和恶寒发热（表证）的区分：恶寒发热→同时出现怕冷和发烧（现在又冷又热），寒热往来→交替出现（现在只冷或只热，过一会儿再变）。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是寒热往来，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（地域差异）：南方疟疾高发区患者出现定时寒热往来→首先考虑疟疾（达原饮）。北方非疟区患者寒热往来无定时→多考虑少阳病（小柴胡汤）。<strong>场景二</strong>（体质差异）：体壮者少阳病→小柴胡汤原方；体虚者少阳病→小柴胡汤加党参、黄芪（扶正祛邪）。<strong>场景三</strong>（兼夹证）：少阳病兼便秘→大柴胡汤（和解+通下）。少阳病兼小便不利→柴胡桂枝干姜汤。寒热往来伴剧烈头痛→注意是否为脑型疟疾，需紧急处理。</div></div></div>'''

# ═══════════════════════════════════════════
# dx-3-1 特殊汗出的临床表现意义
# ═══════════════════════════════════════════
new_content_map['dx-3-1'] = '''<p><strong>自汗、盗汗、绝汗、战汗——四种特殊汗出对应完全不同的病机：气虚、阴虚、亡阳/亡阴、邪正交争的转折点。</strong></p><div class="classic-quote">《素问·阴阳别论》："阳加于阴谓之汗。"汗是阳气蒸化阴液从汗孔排出的产物——汗出异常反映了阴阳关系的失调。<span class="src">——《黄帝内经》</span></div><div class="mnem">自汗气虚白天漏，盗汗阴虚晚上偷；绝汗危重分阴阳，战汗转折细细究。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">四种特殊汗出</span><span class="df-arrow">→</span><span class="df-node df-logic">汗为心之液<br>阳加阴则为汗</span><span class="df-arrow">→</span><span class="df-node df-organ">自汗·盗汗<br>绝汗·战汗</span><span class="df-arrow">→</span><span class="df-node df-symptom">玉屏·归黄<br>参附·生脉</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">"出汗"这件小事——漏汗、偷汗、绝汗、战汗，四种汗四种命</span><div class="ds-body">同样是出汗，有人白天坐着不动就冒汗（自汗）、有人晚上睡着了出一身汗（盗汗）、有人在危重时刻大汗淋漓（绝汗）、有人在高烧后突然出一身透汗（战汗）。中医把这些"特殊汗出"看作身体在发出不同的信号。问诊中要问清楚：什么时间出汗？出汗的部位？汗的温度和黏度？出完汗感觉更舒服还是更虚弱？每一个细节都指向不同的病机。</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">四种汗出的病机分析——从"汗"看到体内的水火关系</span><div class="ds-body">汗是"阳气蒸化阴液"的产物——有足够的阴液作为原料，有足够的阳气作为热源，还要有正常的腠理（毛孔）开合功能，才能正常出汗。自汗（白天不动也出汗）→气虚不能固摄腠理→毛孔关不紧→漏汗。盗汗（入睡出汗、醒则汗止）→阴虚不能制阳→入睡后阳气入阴、虚火蒸腾阴液→偷汗。绝汗（危重时的大汗）→辨阴阳：冷汗清稀如水+肢厥→亡阳；热汗黏稠如油+身热→亡阴。战汗（发热后突然全身战栗出汗）→邪正交争的转折点：正胜邪退→汗出热退脉静身凉；邪胜正衰→汗出热不退。战汗是最"戏剧性"的汗——它意味着正邪正在决胜负。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——四种汗出各有不同的特征和治法</span><div class="ds-body"><strong>自汗</strong>——白天稍动或不动即出汗，伴神疲乏力、气短懒言、面色淡白、易感冒。舌淡苔白、脉虚弱。病机为气虚卫外不固。代表方玉屏风散（益气固表止汗）。气虚明显加四君子汤。<strong>盗汗</strong>——入睡即出汗、醒后汗止（"盗"意为偷偷地），伴五心烦热、口干咽燥、颧红、舌红少苔、脉细数。病机为阴虚火旺。代表方当归六黄汤（滋阴泻火固表）。阴虚为主用六味地黄丸。<strong>绝汗（脱汗）</strong>——危重时大汗淋漓。亡阳：冷汗清稀如水、四肢厥冷、脉微欲绝→参附汤回阳救逆。亡阴：汗热黏稠如油、身热烦躁、脉细数→生脉散益气救阴。临床常阴阳两脱，需参附+生脉同用。<strong>战汗</strong>——发热过程中突然全身战栗、随后大汗出。汗出热退脉静→正胜邪退（病愈向好转）；汗出热不退、烦躁→邪胜正衰（病情恶化）。治疗原则：战汗时不必用药，密切观察。汗出后注意补液和调护。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——自汗与盗汗、绝汗中亡阳与亡阴最容易误判的要点</span><div class="ds-body">自汗和盗汗的鉴别是基础考点：自汗→白天+不动也汗+气虚→玉屏风散。盗汗→睡着+醒来就停+阴虚→当归六黄汤。但临床最常见的混淆是"气虚自汗"和"气阴两虚自汗+盗汗并存"——很多病人白天也出汗、晚上也出汗，这是因为气阴两虚了，需要气阴双补（生脉散+玉屏风散）。亡阳和亡阴的鉴别是危重证的关键：核心看"汗"——亡阳→冷汗清稀如水（摸上去冷、不黏手）+四肢厥冷；亡阴→热汗黏腻如油（摸上去温热、黏手）+身热肢温。两组表现一字之差，治法却完全相反——参附汤（温热）vs 生脉散（甘凉）。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是出汗异常，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（更年期女性）：潮热+自汗+盗汗同时出现——肾阴虚、阴阳失调→二仙汤合六味地黄丸。<strong>场景二</strong>（大病初愈）：自汗乏力、稍动则喘→肺脾气虚→玉屏风散合四君子汤。<strong>场景三</strong>（肥胖体质）：白天汗多、动则尤甚、汗黏不爽→气虚夹湿→防己黄芪汤加减。<strong>场景四</strong>（手术后）：术后虚汗多→气血两虚→八珍汤加浮小麦、麻黄根。</div></div></div>'''

# ═══════════════════════════════════════════
# dx-4-2 头痛胸痛胁痛胃脘痛腹痛的要点
# ═══════════════════════════════════════════
new_content_map['dx-4-2'] = '''<p><strong>不同部位的疼痛对应不同的脏腑经络——头痛分经、胸胁脘腹各有所属，问诊中要辨清疼痛部位和性质的组合。</strong></p><div class="classic-quote">《素问·举痛论》："经脉流行不止、环周不休，寒气入经而稽迟，涩而不行，客于脉外则血少，客于脉中则气不通，故卒然而痛。"<span class="src">——《黄帝内经》</span></div><div class="mnem">头痛太阳后阳明前，少阳两侧厥阴巅；胸闷痰饮刺痛瘀，胁胀肝郁刺痛瘀。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">疼痛部位辨证</span><span class="df-arrow">→</span><span class="df-node df-logic">不通则痛<br>不荣则痛</span><span class="df-arrow">→</span><span class="df-node df-organ">头痛分经<br>胸胁脘腹各有所属</span><span class="df-arrow">→</span><span class="df-node df-symptom">川芎茶调·血府逐瘀<br>柴胡疏肝·丹参饮</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">"头痛"——同一个头，不同的位置指向不同的经脉和脏腑</span><div class="ds-body">同样是头痛，有人痛在后脑勺（太阳经）、有人痛在前额（阳明经）、有人在太阳穴两侧胀痛（少阳经）、有人在头顶痛（厥阴经）。中医的"头痛分经"理论来自于经络循行：每条经络都有自己的"管辖范围"，所以疼痛的部位就揭示了是哪条经络出了问题。除了分经，还要分性质：胀痛（气滞）、刺痛（瘀血）、重痛（湿邪）、灼痛（火热）、冷痛（寒邪/阳虚）。相同部位的疼痛+不同性质=不同的治法。</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">疼痛的病机分析——"不通"和"不荣"两大总纲</span><div class="ds-body">疼痛的病机不外乎两种："不通则痛"和"不荣则痛"。不通则痛→实邪阻塞经络、气血运行不畅→痛势剧烈、拒按。气滞胀痛（柴胡疏肝散）、瘀血刺痛（血府逐瘀汤）、寒凝冷痛（良附丸）、湿热灼痛（龙胆泻肝汤）。不荣则痛→气血阴阳亏虚、脏腑经络失养→痛势绵绵、喜按。气虚隐痛（补中益气汤）、血虚隐痛（四物汤）、阳虚冷痛（理中汤）、阴虚灼痛（一贯煎）。问诊中区分疼痛性质的"拒按"与"喜按"是辨虚实的关键切入点。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——不同部位的疼痛各有辨证要点</span><div class="ds-body"><strong>头痛分经</strong>——太阳经（后脑勺）：风寒湿邪多见→川芎茶调散。阳明经（前额、眉棱骨）：阳明热盛→白虎汤或清胃散。少阳经（两侧太阳穴）：肝胆郁热→小柴胡汤或龙胆泻肝汤。厥阴经（巅顶）：寒凝厥阴→吴茱萸汤。<strong>胸痛</strong>——胸闷痛+痰多+苔腻→痰浊阻肺→瓜蒌薤白半夏汤。刺痛固定+夜间重→心血瘀阻→血府逐瘀汤。胸痛彻背+喘息→真心痛（心梗）→急服苏合香丸。<strong>胁痛</strong>——胀痛走窜+情绪波动→肝气郁结→柴胡疏肝散。刺痛固定+胁下痞块→瘀血阻络→血府逐瘀汤或旋覆花汤。<strong>胃脘痛</strong>——食后痛甚+胀满→食滞胃脘→保和丸。空腹痛甚+喜按→脾胃虚寒→黄芪建中汤。胃脘灼痛+反酸→肝胃郁热→左金丸。<strong>腹痛</strong>——绕脐痛+便秘→阳明腑实→大承气汤。少腹冷痛+得热减轻→寒凝肝脉→暖肝煎。腹痛泄泻+泻后痛减→肝郁脾虚→痛泻要方。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——头痛中最容易误判的经与经之间的"交界痛"</span><div class="ds-body">头痛分经最容易误判的是疼痛在两条经的交界处。例如，前额痛连眉棱骨→既可能是阳明经，也可能是厥阴经出前额。这时要看伴随症状：若伴鼻塞流涕、前额闷胀→阳明经；若伴巅顶跳痛、恶心→厥阴经。另一个难点是"全头痛"——整个头部都痛→可能是太阳经（太阳主一身之表，外感头痛多见全头痛）、也可能是气血亏虚（清窍失养）。鉴别点：外感全头痛→恶寒发热、脉浮紧；气血亏虚全头痛→劳累加重、脉细弱。胁痛中"肝气郁结"和"瘀血阻络"的鉴别：肝郁→胀痛窜走、情绪影响明显；瘀血→刺痛不移、夜间加重、舌有瘀斑。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是头痛，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（年轻人 vs 中老年）：25岁姑娘经期头痛（经前发作、胀痛、两侧）→肝郁血瘀→逍遥散合桃红四物汤。50岁男性高血压头痛（后脑勺胀痛、面红）→肝阳上亢→天麻钩藤饮。<strong>场景二</strong>（紧张型 vs 偏头痛）：工作压力大整日头痛（全头紧束感如戴帽）→气血郁滞→柴胡疏肝散合四物汤。偏头痛反复发作（一侧搏动性痛+恶心）→少阳经气不利→散偏汤。<strong>场景三</strong>（胸痛危急鉴别）：胸痛彻背+冷汗+气短→真心痛（心梗），需立即急救。胸痛位置固定+按压痛甚→肋间神经痛或软组织损伤，可用复元活血汤。</div></div></div>'''

# ═══════════════════════════════════════════
# dx-4b-1 头晕
# ═══════════════════════════════════════════
new_content_map['dx-4b-1'] = '''<p><strong>头晕的四种常见证型——肝阳上亢、气血亏虚、痰湿内阻、肾精不足，需结合伴随症状和诱因进行鉴别。</strong></p><div class="classic-quote">《灵枢·口问》："上气不足，脑为之不满，耳为之苦鸣，头为之苦倾，目为之眩。"<span class="src">——《黄帝内经》</span></div><div class="mnem">晕胀肝阳天麻钩，晕白气血归脾收；晕重痰湿半夏术，晕鸣肾精左归求。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">头晕<br>四种病机</span><span class="df-arrow">→</span><span class="df-node df-logic">清窍失养<br>或邪扰清空</span><span class="df-arrow">→</span><span class="df-node df-organ">胀痛·面白·重裹·耳鸣</span><span class="df-arrow">→</span><span class="df-node df-symptom">天麻钩·归脾<br>半夏天麻·左归</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">"头晕"——同样是天旋地转，病因可能完全不同</span><div class="ds-body">三个人都说"头晕"：一个说"头晕胀痛、血压高、面红耳赤"，一个说"蹲下站起来就眼前发黑"，还有一个说"头晕好像头上裹了块湿毛巾、身体沉重"。虽然都叫"头晕"，但中医透过"伴随症状"这个窗口看到了不同的病因——肝阳上亢是"气往上冲"导致头晕，气血亏虚是"头顶的血不够"导致头晕，痰湿内阻是"湿气蒙蔽了清窍"导致头晕。问诊中要问：除了头晕还有什么不舒服？什么情况下会加重？头晕的时候看东西转不转？</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">头晕的病机分析——"头是诸阳之会"出了问题</span><div class="ds-body">中医讲"头为诸阳之会、精明之府"——所有的阳气都汇聚到头部，大脑需要足够的气血和清阳之气来维持正常功能。头晕的病机归根结底有两类：一是"清窍失养"——气血亏虚或肾精不足→供不上足够的营养给头部（虚证）；二是"邪扰清空"——肝阳上亢（气火往上冲）或痰湿内阻（浊气蒙蔽）→干扰了头部的正常功能（实证/虚实夹杂）。肝阳上亢：肝肾阴虚→肝阳亢盛于上→气血随之上冲→头晕胀痛。气血亏虚：脾胃虚弱+失血→气血不能上荣于脑→头晕面白。痰湿内阻：脾失运化→痰湿内生→上蒙清窍→头晕重如裹。肾精不足：肾虚不能生髓→髓海空虚→头晕耳鸣。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——四种头晕各有不同的"标志性信号"</span><div class="ds-body"><strong>肝阳上亢</strong>——头晕胀痛+面红目赤+急躁易怒+失眠多梦+血压升高+舌红苔黄+脉弦有力。病机为肝肾阴亏、肝阳亢逆。代表方天麻钩藤饮（平肝潜阳）。注意与肝火上炎鉴别：肝阳上亢是本虚标实（下面肝肾阴虚、上面肝阳亢），肝火上炎是纯实热——前者用天麻钩藤饮（平肝+滋补），后者用龙胆泻肝汤（纯清）。<strong>气血亏虚</strong>——头晕+面色淡白或萎黄+神疲乏力+心悸失眠+蹲起发黑+劳累加重+舌淡+脉细弱。病机为气血不足、清窍失养。代表方归脾汤或八珍汤（益气养血）。<strong>痰湿内阻</strong>——头晕重如裹+头昏沉闷胀+胸闷呕恶+纳呆+肢体困重+苔白腻+脉滑。病机为痰湿中阻、清阳不升。代表方半夏白术天麻汤（燥湿化痰、息风止晕）。<strong>肾精不足</strong>——头晕耳鸣+腰膝酸软+健忘+精神萎靡+舌淡+脉沉细。偏阴虚者伴五心烦热（左归丸），偏阳虚者伴畏寒肢冷（右归丸）。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——头晕中最容易误判的肝阳上亢和痰湿内阻</span><div class="ds-body">肝阳上亢和痰湿内阻都可以引起头晕，但治法完全不同——前者要"降火平肝"，后者要"化痰祛湿"。鉴别要点：肝阳上亢→头晕胀痛（感觉血管在跳）+面红+易怒+血压高+苔黄脉弦→天麻钩藤饮。痰湿内阻→头晕重如裹（头被蒙住的感觉）+胸闷+呕恶+苔白腻+脉滑→半夏白术天麻汤。一"胀"一"重"，一"红"一"腻"——这是鉴别的关键词。另外，气血亏虚和肾精不足的鉴别：气血亏虚→蹲起加重+面白+心悸+月经少→补气血；肾精不足→伴腰酸+耳鸣+健忘+齿摇发脱→补肾填精。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是头晕，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（高血压患者）：头晕胀痛+面红+血压升高→肝阳上亢→天麻钩藤饮。若长期血压控制不佳、头晕伴耳鸣+腰酸→阴虚阳亢，加杞菊地黄丸。<strong>场景二</strong>（年轻女性）：经期头晕+面白+月经量少→血虚→四物汤加味。劳累后头晕+乏力+食欲差→脾虚气血不足→归脾汤。<strong>场景三</strong>（老年人）：慢性头晕+耳鸣+健忘+腰酸→肾精不足→左归丸。头晕+走路不稳+肢体麻木→注意中风气虚血瘀→补阳还五汤。<strong>场景四</strong>（颈椎病患者）：转头时头晕加重+颈项强痛→痰瘀阻络→半夏白术天麻汤合通窍活血汤。</div></div></div>'''

# ═══════════════════════════════════════════
# dx-5b-1 耳鸣耳聋
# ═══════════════════════════════════════════
new_content_map['dx-5b-1'] = '''<p><strong>耳鸣耳聋——突发声大为实证（肝火上炎），渐发声细为虚证（肾精不足），辨虚实的关键在起病缓急和声音性质。</strong></p><div class="classic-quote">《灵枢·脉度》："肾气通于耳，肾和则耳能闻五音矣。"<span class="src">——《黄帝内经》</span></div><div class="mnem">突鸣声大肝火龙胆泻，渐鸣声细肾虚左慈丸；实按不减虚按可减，新病久病要细参。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">耳鸣耳聋<br>实虚两途</span><span class="df-arrow">→</span><span class="df-node df-logic">实→肝火上扰<br>虚→肾精亏虚</span><span class="df-arrow">→</span><span class="df-node df-organ">突发声大按不减<br>vs渐进声细按可减</span><span class="df-arrow">→</span><span class="df-node df-symptom">龙胆泻肝汤<br>vs耳聋左慈丸</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">"耳朵嗡嗡响"——有人像潮水有人像蝉鸣，声音就是诊断信号</span><div class="ds-body">两个耳鸣病人走进诊室：一个说"耳朵突然嗡嗡响、声大得像潮水、按着还响"，另一个说"耳鸣好几年了、声音像蝉叫（吱——）、晚上安静时更明显、用手按着会好一点"。同样是耳鸣，一个是实证（肝火上炎——火气往上冲），一个是虚证（肾精不足——耳朵的营养不够了）。中医问诊治耳鸣的第一问就是：耳鸣是突然出现的还是慢慢加重的？声音是大还是小？用手按耳朵会好转还是没变化？</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">耳鸣耳聋的病机分析——"肾开窍于耳"和"肝胆绕耳"</span><div class="ds-body">耳与两个脏腑有密切关系：肾开窍于耳（耳朵的听力靠肾精滋养），肝胆的经络绕行于耳（肝胆之气可以"上冲"到耳朵）。所以耳鸣耳聋的病因分虚实两大类：实证→肝胆之火上扰→"火"顺着经络冲到耳朵→耳鸣声大如潮、突发→龙胆泻肝汤清肝胆实火。虚证→肾精不足→耳朵得不到足够的精血供养→听力逐渐下降、耳鸣声细如蝉→耳聋左慈丸滋肾填精。另外还有痰火上扰（耳鸣+胸闷+苔黄腻→温胆汤）和气血瘀阻（外伤后耳鸣+舌紫暗→通窍活血汤）等兼夹证。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——实火和肾虚的鉴别要点</span><div class="ds-body"><strong>肝火上炎（实证）</strong>——突发耳鸣耳聋、声大如潮或如雷、按之不减。伴头痛面红、目赤口苦、烦躁易怒、胁痛、大便秘结、小便黄。舌红苔黄、脉弦数有力。病机为肝气郁结化火、火性上炎、循经上扰耳窍。代表方龙胆泻肝汤（清泻肝胆实火）。<strong>肾精不足（虚证）</strong>——渐进耳鸣耳聋、声细如蝉鸣、按之可减轻。伴头晕目眩、腰膝酸软、健忘失眠、口干咽燥。偏阴虚加五心烦热、舌红少苔、脉细数（耳聋左慈丸：六味地黄丸加磁石、五味子）。偏阳虚加畏寒肢冷、舌淡、脉沉迟（右归丸）。<strong>痰火郁结（实证）</strong>——耳鸣声如机器轰鸣、时轻时重。伴胸闷痰多、口苦黏腻、二便不畅。舌红苔黄腻、脉滑数。代表方温胆汤加礞石、黄芩。（介于纯实和纯虚之间的兼夹证）</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——"按之"减轻还是不减轻——最简单的虚实鉴别法</span><div class="ds-body">耳鸣最简单实用的虚实鉴别方法就是"按耳朵"：用手掌按住耳廓轻轻按压→耳鸣减轻或消失→虚证（按的时候让气血暂时回流到耳朵，减轻了虚性耳鸣）。按了反而更响或没变化→实证（按了之后火气被堵、冲得更厉害）。这个"按耳鉴别法"在临床问诊中非常实用。另外还需要注意：老年人耳鸣大部分是肾虚（加减退的生理性衰退），但也有老年耳鸣伴高血压、面红→肝阳上亢→天麻钩藤饮加味。同一个病人可以虚实夹杂——既有肾精不足的基础、又因为生气导致肝火上冲、两者相加导致耳鸣加重→治法要标本兼顾（左归丸合龙胆泻肝汤加减）。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是耳鸣，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（年轻人 vs 老年人）：25岁因熬夜+暴怒后突发耳鸣、声大面红口苦→肝火上炎→龙胆泻肝汤。70岁渐进耳鸣多年、声细如蝉、伴腰酸健忘→肾精不足→耳聋左慈丸。<strong>场景二</strong>（感冒后）：感冒后耳闷耳鸣、伴鼻塞咳嗽→风热上扰耳窍→银翘散加辛夷、苍耳子。注意和肝火的区别：感冒后耳鸣多伴耳闷感（像有东西堵住），肝火耳鸣是"轰隆隆"的响。<strong>场景三</strong>（职业因素）：长期在噪音环境中工作→耳鸣声高、听力下降、伴头晕→实证为主、气火上逆→龙胆泻肝汤合通窍活血汤。长期用耳机→耳鸣如蝉、听力下降→多虚少实→六味地黄丸。</div></div></div>'''

