# dx-8b-2 小便异常
# ═══════════════════════════════════════════
new_content_map['dx-8b-2'] = '''<p><strong>小便异常——尿频辨虚实（湿热下注 vs 肾阳虚），涩痛为淋证，余沥不尽为肾气虚，失禁为肾气不固。</strong></p><div class="classic-quote">《素问·灵兰秘典论》："膀胱者，州都之官，津液藏焉，气化则能出矣。"<span class="src">——《黄帝内经》</span></div><div class="mnem">尿频湿热八正散，夜尿肾阳肾气丸；涩痛淋证分清饮，余沥肾虚缩泉丸。</div><div class="derive-box"><div class="derive-flow"><span class="df-node df-concept">小便异常<br>气化失常</span><span class="df-arrow">→</span><span class="df-node df-logic">膀胱气化不利<br>肾司二便失常</span><span class="df-arrow">→</span><span class="df-node df-organ">尿频·涩痛<br>余沥·失禁</span><span class="df-arrow">→</span><span class="df-node df-symptom">八正·分清<br>缩泉·肾气丸</span></div><div class="derive-step ds-blue"><span class="ds-num">1</span><span class="ds-title">"小便的问题"——排尿的频率、感觉、控制力都是诊断信号</span><div class="ds-body">两个病人都说"小便多"——一个说"小便次数多、尿的时候尿道灼痛、尿黄"（小便频数涩痛→湿热下注），另一个说"晚上要起来三四次、尿清长、每次量不少"（夜尿多清长→肾阳虚）。虽然都叫"尿频"，但一个湿热一个虚寒，治法完全相反。问小便要问：一天几次（白天和晚上分别）？尿的时候痛不痛？尿的颜色是黄还是清？有没有尿不干净的感觉？能不能控制住？这些细节决定了是清热还是温补。</div></div><div class="derive-step ds-red"><span class="ds-num">2</span><span class="ds-title">小便异常的病机分析——"膀胱者州都之官，气化则能出矣"</span><div class="ds-body">《内经》说膀胱的功能是"气化则能出"——小便的排出依赖于"气化"功能（肾阳的蒸腾和膀胱的气化）。如果气化功能正常→小便通畅、次数适中。如果气化失常→小便异常。湿热下注→湿热之邪蕴结膀胱→"热"刺激膀胱壁→尿频急迫（想尿但忍不住）+涩痛（尿的时候像刀割/灼热）→八正散清热利湿。肾阳虚→肾阳不足→膀胱气化功能减退→夜尿增多（夜间阳气更弱）→金匮肾气丸温阳。肾气虚→肾的固摄功能减退→小便余沥不尽（尿完还想尿）→缩泉丸或金匮肾气丸。肾气不固→严重的话就小便失禁（控不住了）。热淋（急性尿路感染）→湿热下注为主→八正散；劳淋（慢性反复发作）→虚实夹杂→八正散合知柏地黄丸。</div></div><div class="derive-step ds-purple"><span class="ds-num">3</span><span class="ds-title">分型锁定——小便异常的几种常见类型</span><div class="ds-body"><strong>尿频</strong>——<strong>湿热下注</strong>：小便频数+尿急+尿道灼痛+尿色黄赤+伴小腹拘急、口渴、舌红苔黄腻、脉滑数。病机为湿热蕴结膀胱→气化不利。代表方八正散（清热利湿通淋）。<strong>肾阳虚</strong>：夜尿增多（夜尿3次以上）+小便清长+伴畏寒肢冷、腰膝酸冷、神疲乏力、舌淡胖苔白滑、脉沉迟无力。病机为肾阳不足、膀胱气化失司。代表方金匮肾气丸（温补肾阳、化气利水）。<strong>涩痛（淋证）</strong>——小便涩滞不畅、尿道疼痛。热淋→灼热刺痛+尿黄+苔黄腻→八正散。血淋→尿血+涩痛→小蓟饮子或导赤散。石淋→尿中夹砂石+涩痛→石韦散。气淋→少腹胀满+小便涩滞→沉香散。膏淋→小便如米泔水→萆薢分清饮。<strong>余沥不尽</strong>——小便后仍有尿液点滴排出（尿不干净），伴腰膝酸软、神疲乏力。病机为肾气虚、膀胱固摄无权。代表方缩泉丸或金匮肾气丸（补肾缩尿）。<strong>失禁</strong>——小便不能控制、随时自行流出。病机为肾气不固、膀胱失约。代表方桑螵蛸散或固脬汤。</div></div><div class="derive-step ds-orange"><span class="ds-num">4</span><span class="ds-title">鉴别对比——"尿频"中湿热和下虚寒最容易被混淆的要点</span><div class="ds-body">尿频的虚实鉴别是临床最常用的考点：湿热尿频→尿频+痛（涩痛、灼痛）+尿黄赤+苔黄腻+脉数→实热证→八正散清热。肾虚尿频→夜尿多+尿清长+无涩痛+腰酸+舌淡+脉沉迟→虚寒证→金匮肾气丸温补。但还有一种情况最容易误判——老年人前列腺增生：既有夜尿多（肾虚）又有排尿涩痛（湿热/瘀血），这是虚实夹杂。治法要"攻补兼施"——先清利湿热（八正散）后温补肾阳（肾气丸）或两者同用。另外，余沥不尽（尿不干净）在小便结束后仍有尿意——这是肾气虚的典型表现，不是湿热。注意和"尿后白浊"鉴别：余沥→尿后仍有尿液（清）；白浊→尿后有白色黏液滴出→湿浊下注。</div></div><div class="derive-step ds-orange"><span class="ds-num">5</span><span class="ds-title">同是小便异常，不同的人不同的病根</span><div class="ds-body"><strong>场景一</strong>（男性 vs 女性）：男性夜尿多+排尿费力+尿线细→前列腺增生（肾虚+瘀血）→桂枝茯苓丸合金匮肾气丸。女性尿频+尿急+尿痛→急性尿路感染（湿热下注）→八正散。<strong>场景二</strong>（小儿 vs 老人）：小儿遗尿（5岁以上仍尿床）→肾气未充+脾肺气虚→缩泉丸合补中益气汤。老人小便失禁→肾气不固、膀胱失约→桑螵蛸散。<strong>场景三</strong>（糖尿病）：多尿+多饮+多食+消瘦→消渴病→上消（肺热）白虎加人参汤、中消（胃火）玉女煎、下消（肾虚）六味地黄丸。<strong>场景四</strong>（妊娠后期）：小便频数+小腹坠胀→胎气下迫膀胱→补中益气汤（提升气机），一般产后恢复。</div></div></div>'''

# ── 3. Build replacement map ──
# For each point, we need to find the old content and replace it with new content
# The new content = new_core_content (with summary, classic-quote, mnem, derive-box) + original trailing elements

# First, extract original trailing elements from each point
trailing_map = {}

# Find each point and extract its trailing elements
for pid in new_content_map:
    # Find the point
    pattern = f"id:'{pid}'"
    pos = content.find(pattern)
    if pos < 0:
        print(f"ERROR: Cannot find {pid}")
        continue
    
    # Find the content field
    c_pos = content.find("content:'", pos)
    if c_pos < 0:
        print(f"ERROR: Cannot find content for {pid}")
        continue
    
    c_start = c_pos + 9  # skip 'content:''
    
    # Find the end of content (the ' that's followed by } or ,})
    # Scan from c_start and look for ' followed by , or }
    end = -1
    i = c_start
    while i < len(content):
        if content[i] == "'":
            # Check next char
            next_i = i + 1
            while next_i < len(content) and content[next_i] in ' \t\n':
                next_i += 1
            if next_i < len(content) and content[next_i] in ',}':
                end = i
                break
        i += 1
    
    if end < 0:
        print(f"ERROR: Cannot find content end for {pid}")
        continue
    
    old_content = content[c_start:end]
    
    # Extract the original trailing elements
    # The old content starts with <p>...</p> and then has trailing elements
    # We need to keep compare-table, trap-box, clinical-case, mini-quiz (but NOT clq, plain, or mnem since we replace them)
    # Actually from the design doc: keep compare-table, trap-box, clinical-case
    
    # Find all trailing elements after the initial <p> and any plain/clq/mnem that we'll replace
    trailing = ''
    
    # Strategy: keep compare-table, trap-box, clinical-case, mini-quiz
    # Remove: clq, plain (we replace with proper classic-quote and integrate into derive-box)
    # We already have classic-quote and mnem in new content
    
    # Find all elements to keep by scanning for them
    keep_tags = ['compare-table', 'trap-box', 'clinical-case', 'mini-quiz']
    keep_elements = []
    
    for tag in keep_tags:
        tag_pos = 0
        while True:
            tag_start = old_content.find(f'<div class={tag}', tag_pos)
            if tag_start == -1:
                tag_start = old_content.find(f'<div class="{tag}"', tag_pos)
            if tag_start == -1:
                break
            
            # Find the closing </div> for this element
            # Count depth
            depth = 1
            scan_pos = tag_start + len(f'<div class={tag}>') if f'<div class={tag}>' in old_content[tag_start:tag_start+100] else tag_start
            # Actually let's find the actual > that closes the opening div
            gt_pos = old_content.find('>', tag_start)
            if gt_pos == -1:
                break
            scan_pos = gt_pos + 1
            
            while depth > 0 and scan_pos < len(old_content):
                if old_content[scan_pos:scan_pos+4] == '<div':
                    depth += 1
                    scan_pos += 4
                elif old_content[scan_pos:scan_pos+5] == '</div':
                    depth -= 1
                    scan_pos += 5
                else:
                    scan_pos += 1
            
            element_text = old_content[tag_start:scan_pos]
            keep_elements.append(element_text)
            tag_pos = scan_pos
    
    # Join trailing elements (they might be in wrong order, but that's OK for compare-tables etc.)
    # Reorder by original position
    if keep_elements:
        # Sort by original position
        keep_elements.sort(key=lambda e: old_content.find(e[:30]))
        trailing = ''.join(keep_elements)
    
    trailing_map[pid] = trailing
    print(f"{pid}: old content = {len(old_content)}B, trailing = {len(trailing)}B")

# ── 4. Perform replacement ──
for pid in new_content_map:
    new_full = new_content_map[pid] + trailing_map[pid]
    
    # Find old content
    pattern = f"id:'{pid}'"
    pos = content.find(pattern)
    c_pos = content.find("content:'", pos)
    c_start = c_pos + 9
    
    # Find end
    end = -1
    i = c_start
    while i < len(content):
        if content[i] == "'":
            next_i = i + 1
            while next_i < len(content) and content[next_i] in ' \t\n':
                next_i += 1
            if next_i < len(content) and content[next_i] in ',}':
                end = i
                break
        i += 1
    
    if end < 0:
        print(f"ERROR: Cannot find content end for {pid}")
        continue
    
    old_full = content[c_start:end]
    
    # Replace
    before = content[:c_start]
    after = content[end:]
    content = before + new_full + after
    
    print(f"{pid}: replaced {len(old_full)}B → {len(new_full)}B (+{len(new_full)-len(old_full)}B)")

# ── 5. Fix comma between units ──
content = content.replace("]}]}{unit:'", "]}]},{unit:'")

# ── 6. Write result ──
with open(FILE, 'w', encoding='utf-8') as f:
    f.write(content)

print(f"\n=== DONE ===")
print(f"Original size: {len(orig_content)} bytes")
print(f"New size: {len(content)} bytes")
print(f"Delta: +{len(content) - len(orig_content)} bytes")
